> +			return -EINVAL;
> +		}
> +	case IIO_CHAN_INFO_PHASE:
> +		if (val < 0 || val2 < 0)
> +			return -EINVAL;
> +
> +		tmp64 = (u64)val * MICRO + val2;
> +		if (tmp64 >= AD9910_MAX_PHASE_MICRORAD)
> +			return -EINVAL;
> +
> +		tmp64 = DIV_U64_ROUND_CLOSEST(tmp64 << 16, AD9910_MAX_PHASE_MICRORAD);
