> +						   AD9910_PROFILE_ST_ASF_MSK,
> +						   tmp64, true);
> +		default:
> +			return -EINVAL;
> +		}
> +	case IIO_CHAN_INFO_SAMP_FREQ:
> +		return ad9910_set_sysclk_freq(st, val, true);
> +	case IIO_CHAN_INFO_SCALE:
> +		switch (chan->address) {
> +		case AD9910_CHAN_IDX_PHY:
> +			if (val != 0 || val2 < 0)
> +				return -EINVAL;
> +
> +			tmp32 = DIV_U64_ROUND_CLOSEST((u64)val2 << 14,
