+		cmd->expires = jiffies + HCI_CMD_TIMEOUT;
+		data->raw_vendor_cmd_submitted++;
+		submitted = cmd;
+		break;
+	}
+
+	if (submitted)
+		btusb_raw_vendor_cmd_schedule_locked(data);
+	spin_unlock_irqrestore(&data->remote_wakeup_lock, flags);
